-- Content patch: Pokémon forms — regional forms, Mega Evolutions, Giratina's Origin Forme and Arceus's types.
-- The same rows the full seed.sql now carries, for a live database that is otherwise up to date.
-- Paste it into the Supabase SQL editor and run it once; running it again changes nothing but the version bump.
--
--   · pokemon.form  — new jsonb column (also migrations/0030_pokemon_forms.sql)
--   · 227 form rows — 57 regional forms; 92 Megas, Primal Kyogre / Groudon, Ultra Necrozma; 32 Gigantamax;
--                     the forms taken below half HP (Giratina, Darmanitan ×2, Zygarde, Wishiwashi, Minior); Arceus,
--                     Silvally ×17 and Ogerpon ×3 (dex 10007+, 20001+, 20101+)
--   · 21 species    — evolutions rewritten for the regional forms (Pikachu → Alolan Raichu in Alola, Meowth's
--                     Perrserker branch moved to Galarian Meowth, …)
--   · wild pools    — Alola, Galar, Hisui (Space-Time Rift) and Paldea forms; West Province's plain Tauros at weight 0
--   · trainers      — Alola, Galar and Paldea trainers with their regional forms
--   · Dyna Tree Hill — a new Galar secret area: Galarian Articuno, Zapdos and Moltres
--   · items         — Galarica Cuff and Galarica Wreath (Isle of Armor), Ice Stone (Circhester), Sun Stone (Rift)
--
-- Mega Evolution, Gigantamax, the TYPE menu, the forms below half HP and what trainers do with them are app code:
-- they ship with the deploy, not with this file. So do the form sprites in public/pokemon.
begin;

alter table areas add column if not exists scale_offsets jsonb;
alter table areas add column if not exists rounds_to_clear int;
alter table items add column if not exists shop_area uuid;
alter table items add column if not exists region text;
alter table items add column if not exists once_only boolean not null default false;
alter table pokemon add column if not exists form jsonb;

on conflict (dex) do update set name = excluded.name, type1 = excluded.type1, type2 = excluded.type2, base_hp = excluded.base_hp, max_hp = excluded.max_hp, speed = excluded.speed, sprite_url = excluded.sprite_url, dice = excluded.dice, rerolls = excluded.rerolls, catch_value = excluded.catch_value, evolutions = excluded.evolutions, milestones = excluded.milestones, notes = excluded.notes, form = excluded.form;

on conflict (id) do update set order_index = excluded.order_index, region_id = excluded.region_id, name = excluded.name, banner_url = excluded.banner_url, rounds_to_clear = excluded.rounds_to_clear, min_level = excluded.min_level, max_level = excluded.max_level, encounter_weights = excluded.encounter_weights, backtrack_multiplier = excluded.backtrack_multiplier, legendary_boss = excluded.legendary_boss, scales_to_team = excluded.scales_to_team, scale_offsets = excluded.scale_offsets, easy_mode = excluded.easy_mode, enemy_upgrade_level = excluded.enemy_upgrade_level, battle_background = excluded.battle_background, hidden = excluded.hidden, unlock_conditions = excluded.unlock_conditions, gyms = excluded.gyms;

on conflict (id) do update set name = excluded.name, sprite_url = excluded.sprite_url, team = excluded.team, role = excluded.role, badge = excluded.badge, upgrade_level = excluded.upgrade_level, battle_background = excluded.battle_background, rival_of = excluded.rival_of, items = excluded.items;

on conflict (id) do update set area_id = excluded.area_id, dex = excluded.dex, weight = excluded.weight, min_level = excluded.min_level, max_level = excluded.max_level;

on conflict (id) do update set area_id = excluded.area_id, item_key = excluded.item_key, weight = excluded.weight, unique_find = excluded.unique_find, min_qty = excluded.min_qty, max_qty = excluded.max_qty;

on conflict (key) do update set name = excluded.name, description = excluded.description, sprite_url = excluded.sprite_url, price = excluded.price, effect = excluded.effect, in_shop = excluded.in_shop, shop_badges = excluded.shop_badges, shop_area = excluded.shop_area, region = excluded.region, once_only = excluded.once_only;

-- What Admin → Publish does: a new content version makes every client fetch the new rows on its next load.
update game_config set value = to_jsonb((value #>> '{}')::int + 1) where key = 'configVersion';

commit;
